//! The generator: Kotlin-like data classes as text, one file per declaration. It runs the same
//! lowering and name allocation as the built-in backends, from the published crates.

use tsurara_backend::OutputFile;
use tsurara_lower::tir::{DeclKind, Expr};
use tsurara_lower::{Capabilities, allocate, lower};
use tsurara_naming::{Context, NamingPolicy, camel_case, pascal_case};
use tsurara_sem::{Model, Warning};

/// The first line of every generated file.
pub const MARKER: &str = "// Generated by the example backend. Do not edit.";

/// Kotlin-like names: PascalCase types, camelCase members and functions, keywords escaped.
pub struct Policy;

const KEYWORDS: &[&str] = &[
    "class", "fun", "object", "val", "var", "when", "is", "in", "Any", "String",
];

impl NamingPolicy for Policy {
    fn convert(&self, context: Context, raw: &str, _preserve: bool) -> String {
        let s = match context {
            Context::Type | Context::File => pascal_case(raw),
            Context::Constant => pascal_case(raw).to_uppercase(),
            _ => camel_case(raw),
        };
        match s.chars().next() {
            None => "Value".into(),
            Some(c) if c.is_ascii_digit() => format!("_{s}"),
            Some(_) => s,
        }
    }

    fn is_reserved(&self, _context: Context, ident: &str) -> bool {
        KEYWORDS.contains(&ident)
    }

    fn reserved_suffix(&self, context: Context) -> &str {
        match context {
            Context::Type | Context::File => "Model",
            _ => "_",
        }
    }
}

fn ty(e: &Expr, names: &[String]) -> String {
    match e {
        Expr::Named { decl, .. } => names[decl.0].clone(),
        Expr::List(item) => format!("List<{}>", ty(item, names)),
        Expr::Map(value) => format!("Map<String, {}>", ty(value, names)),
        Expr::Nullable(inner) => format!("{}?", ty(inner, names)),
        Expr::Bool => "Boolean".into(),
        Expr::Bytes => "ByteArray".into(),
        Expr::Scalar(s) => format!("{s:?}"),
        _ => "Any".into(),
    }
}

/// Generates the files for `model`.
pub fn generate(model: &Model) -> (Vec<OutputFile>, Vec<Warning>) {
    let (module, warnings) = lower(model, &Capabilities::MINIMAL);
    let names = allocate(model, &module, &Policy);
    let type_names: Vec<String> = names.decls.iter().map(|d| d.name.clone()).collect();
    let mut files = Vec::new();
    for (decl, n) in module.decls.iter().zip(&names.decls) {
        let mut body = format!("{MARKER}\n\n");
        match &decl.kind {
            DeclKind::Record(r) => {
                body.push_str(&format!("data class {}(\n", n.name));
                for (f, member) in r.fields.iter().zip(&n.members) {
                    body.push_str(&format!(
                        "    val {member}: {}, // {:?}\n",
                        ty(&f.ty, &type_names),
                        f.wire_name
                    ));
                }
                body.push_str(")\n");
            }
            DeclKind::Enum(_) => {
                body.push_str(&format!(
                    "enum class {} {{ {} }}\n",
                    n.name,
                    n.members.join(", ")
                ));
            }
            DeclKind::Alias(e) => {
                body.push_str(&format!("typealias {} = {}\n", n.name, ty(e, &type_names)));
            }
            _ => body.push_str(&format!("sealed interface {}\n", n.name)),
        }
        files.push(OutputFile {
            path: format!("{}.kt", n.file),
            contents: body,
        });
    }
    let mut api = format!("{MARKER}\n\n");
    for (op, n) in model.operations.iter().zip(&names.operations) {
        api.push_str(&format!(
            "// {} {}\nfun {}()\n",
            op.method, op.path, n.function
        ));
    }
    files.push(OutputFile {
        path: "Api.kt".into(),
        contents: api,
    });
    (files, warnings)
}
